/**
 * Improved Express application with security best practices
 * Enhanced error handling and input validation
 */

const express = require('express');
const helmet = require('helmet');
const rateLimit = require('express-rate-limit');
const { body, query, validationResult } = require('express-validator');
const sanitizeHtml = require('sanitize-html');

const app = express();

// ============================================================================
// SECURITY MIDDLEWARE
// ============================================================================

// Security headers
app.use(helmet({
  contentSecurityPolicy: {
    directives: {
      defaultSrc: ["'self'"],
      scriptSrc: ["'self'"],
      styleSrc: ["'self'"],
      imgSrc: ["'self'", "data:"],
    },
  },
  hsts: {
    maxAge: 31536000,
    includeSubDomains: true,
    preload: true,
  },
}));

// Rate limiting to prevent DDoS attacks
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // limit each IP to 100 requests per windowMs
  message: {
    error: 'Too many requests from this IP, please try again later.',
  },
  standardHeaders: true,
  legacyHeaders: false,
});

// Apply rate limiting to all routes
app.use(limiter);

// Stricter rate limiting for authentication-related endpoints
const authLimiter = rateLimit({
  windowMs: 15 * 60 * 1000,
  max: 5, // 5 requests per 15 minutes
  message: {
    error: 'Too many authentication attempts, please try again later.',
  },
  skipSuccessfulRequests: true,
});

// Parse JSON body with size limit
app.use(express.json({ 
  limit: '10kb', // Prevent large payload attacks
  strict: true,  // Only accept arrays and objects
}));

// ============================================================================
// INPUT VALIDATION & SANITIZATION HELPERS
// ============================================================================

/**
 * Middleware to handle validation errors
 */
const handleValidationErrors = (req, res, next) => {
  const errors = validationResult(req);
  if (!errors.isEmpty()) {
    // Log validation failures for security monitoring
    logSecurityEvent('validation_failed', {
      ip: req.ip,
      path: req.path,
      errors: errors.array(),
    });

    return res.status(400).json({
      error: 'Validation failed',
      details: errors.array().map(err => ({
        field: err.path,
        message: err.msg,
      })),
    });
  }
  next();
};

/**
 * Sanitize string inputs to prevent XSS
 */
const sanitizeInput = (input) => {
  if (typeof input !== 'string') return input;
  return sanitizeHtml(input, {
    allowedTags: [],
    allowedAttributes: {},
  });
};

/**
 * Sanitize all incoming request data
 */
const sanitizeRequest = (req, res, next) => {
  if (req.body) {
    Object.keys(req.body).forEach(key => {
      req.body[key] = sanitizeInput(req.body[key]);
    });
  }
  if (req.query) {
    Object.keys(req.query).forEach(key => {
      req.query[key] = sanitizeInput(req.query[key]);
    });
  }
  if (req.params) {
    Object.keys(req.params).forEach(key => {
      req.params[key] = sanitizeInput(req.params[key]);
    });
  }
  next();
};

app.use(sanitizeRequest);

/**
 * Security event logger (in production, use a proper logging system)
 */
const logSecurityEvent = (eventType, details) => {
  const logEntry = {
    timestamp: new Date().toISOString(),
    eventType,
    ...details,
  };
  // In production: send to SIEM, security monitoring, or log aggregation service
  console.error('[SECURITY]', JSON.stringify(logEntry));
};

// ============================================================================
// CENTRALIZED ERROR HANDLING
// ============================================================================

/**
 * Custom error class for application errors
 */
class AppError extends Error {
  constructor(message, statusCode = 500, isOperational = true) {
    super(message);
    this.statusCode = statusCode;
    this.isOperational = isOperational;
    this.timestamp = new Date().toISOString();
    Error.captureStackTrace(this, this.constructor);
  }
}

/**
 * Async handler wrapper to catch errors in async route handlers
 */
const asyncHandler = (fn) => (req, res, next) => {
  Promise.resolve(fn(req, res, next)).catch(next);
};

/**
 * 404 Not Found handler
 */
app.use((req, res) => {
  logSecurityEvent('not_found', {
    ip: req.ip,
    path: req.path,
    method: req.method,
  });

  res.status(404).json({
    error: 'Resource not found',
    path: req.path,
    timestamp: new Date().toISOString(),
  });
});

/**
 * Global error handler (must be last)
 */
app.use((err, req, res, next) => {
  // Log error details
  console.error('[ERROR]', {
    timestamp: new Date().toISOString(),
    error: err.message,
    stack: err.stack,
    path: req.path,
    method: req.method,
    ip: req.ip,
  });

  // Don't leak error details in production
  const is Development = process.env.NODE_ENV !== 'production';

  const statusCode = err.statusCode || 500;
  const response = {
    error: isDevelopment ? err.message : 'Internal server error',
    timestamp: new Date().toISOString(),
  };

  if (isDevelopment) {
    response.stack = err.stack;
    response.details = err details;
  }

  res.status(statusCode).json(response);
});

// ============================================================================
// ROUTES WITH VALIDATION
// ============================================================================

/**
 * Health check endpoint
 */
app.get('/health', (req, res) => {
  try {
    res.json({ 
      status: 'ok', 
      timestamp: new Date().toISOString(),
      uptime: process.uptime(),
    });
  } catch (error) {
    next(new AppError('Health check failed', 500));
  }
});

/**
 * Get users with optional query parameters
 * Includes input validation for filtering and pagination
 */
app.get('/users', 
  [
    // Validate query parameters
    query('id')
      .optional()
      .isInt({ min: 1 })
      .withMessage('ID must be a positive integer')
      .toInt(),
    query('limit')
      .optional()
      .isInt({ min: 1, max: 100 })
      .withMessage('Limit must be between 1 and 100')
      .toInt(),
    query('offset')
      .optional()
      .isInt({ min: 0 })
      .withMessage('Offset must be a non-negative integer')
      .toInt(),
    query('email')
      .optional()
      .isEmail()
      .withMessage('Email must be valid')
      .normalizeEmail(),
    query('name')
      .optional()
      .isLength({ min: 1, max: 100 })
      .withMessage('Name must be between 1 and 100 characters')
      .trim()
      .escape(),
  ],
  handleValidationErrors,
  asyncHandler(async (req, res) => {
    const { id, limit = 100, offset = 0, email, name } = req.query;

    // Mock user data (in production, fetch from database)
    const allUsers = [
      { id: 1, name: 'Alice', email: 'alice@example.com' },
      { id: 2, name: 'Bob', email: 'bob@example.com' },
      { id: 3, name: 'Charlie', email: 'charlie@example.com' },
    ];

    let filteredUsers = allUsers;

    // Apply filters if provided
    if (id) {
      filteredUsers = filteredUsers.filter(user => user.id === id);
      if (filteredUsers.length === 0) {
        throw new AppError('User not found', 404);
      }
    }

    if (email) {
      filteredUsers = filteredUsers.filter(user => 
        user.email.toLowerCase() === email.toLowerCase()
      );
    }

    if (name) {
      filteredUsers = filteredUsers.filter(user =>
        user.name.toLowerCase().includes(name.toLowerCase())
      );
    }

    // Apply pagination
    const paginatedUsers = filteredUsers.slice(offset, offset + limit);

    res.json({
      data: paginatedUsers,
      meta: {
        total: filteredUsers.length,
        limit,
        offset,
      },
    });
  })
);

/**
 * Create a new user (example of POST with validation)
 */
app.post('/users',
  authLimiter, // Stricter rate limit for writes
  [
    // Validate request body
    body('name')
      .exists()
      .withMessage('Name is required')
      .isLength({ min: 1, max: 100 })
      .withMessage('Name must be between 1 and 100 characters')
      .trim()
      .escape(),
    body('email')
      .exists()
      .withMessage('Email is required')
      .isEmail()
      .withMessage('Email must be valid')
      .normalizeEmail(),
    body('age')
      .optional()
      .isInt({ min: 0, max: 150 })
      .withMessage('Age must be between 0 and 150')
      .toInt(),
  ],
  handleValidationErrors,
  asyncHandler(async (req, res) => {
    const { name, email, age } = req.body;

    // Check for duplicate email (in production, check database)
    const existingUser = { id: 1, name: 'Alice', email: 'alice@example.com' };
    if (email === existingUser.email) {
      throw new AppError('Email already exists', 409);
    }

    // Create user (in production, save to database)
    const newUser = {
      id: Date.now(), // Simple ID generation (use proper ID generation in production)
      name,
      email,
      age: age || null,
      createdAt: new Date().toISOString(),
    };

    logSecurityEvent('user_created', {
      userId: newUser.id,
      email: email, // Consider hashing PII in logs
    });

    res.status(201).json(newUser);
  })
);

/**
 * Get user by ID (example of path parameter validation)
 */
app.get('/users/:id',
  [
    // Validate path parameter
    // Note: express-validator doesn't directly validate path params,
    // we validate manually or use a middleware
  ],
  asyncHandler(async (req, res, next) => {
    const { id } = req.params;

    // Validate and sanitize ID
    const userId = parseInt(id, 10);
    if (isNaN(userId) || userId < 1) {
      return res.status(400).json({
        error: 'Invalid user ID',
        message: 'ID must be a positive integer',
      });
    }

    // Fetch user (in production, from database)
    const users = [
      { id: 1, name: 'Alice', email: 'alice@example.com' },
      { id: 2, name: 'Bob', email: 'bob@example.com' },
    ];

    const user = users.find(u => u.id === userId);

    if (!user) {
      throw new AppError('User not found', 404);
    }

    res.json(user);
  })
);

// ============================================================================
// STARTUP WITH VALIDATION
// ============================================================================

/**
 * Validate environment configuration
 */
const validateConfig = () => {
  const requiredEnvVars = [];
  const missing = requiredEnvVars.filter(envVar => !process.env[envVar]);

  if (missing.length > 0) {
    throw new Error(`Missing required environment variables: ${missing.join(', ')}`);
  }

  const port = parseInt(process.env.PORT || '3000', 10);
  if (isNaN(port) || port < 1 || port > 65535) {
    throw new Error('PORT must be a valid port number (1-65535)');
  }

  return { port };
};

/**
 * Start the server
 */
if (require.main === module) {
  try {
    const config = validateConfig();

    const server = app.listen(config.port, () => {
      console.log(`Server running on port ${config.port}`);
      console.log(`Environment: ${process.env.NODE_ENV || 'development'}`);
    });

    // Graceful shutdown
    const gracefulShutdown = (signal) => {
      console.log(`\n${signal} received. Starting graceful shutdown...`);
      server.close(() => {
        console.log('Server closed.');
        process.exit(0);
      });

      // Force shutdown after 10 seconds
      setTimeout(() => {
        console.error('Forced shutdown after timeout.');
        process.exit(1);
      }, 10000);
    };

    process.on('SIGTERM', () => gracefulShutdown('SIGTERM'));
    process.on('SIGINT', () => gracefulShutdown('SIGINT'));

  } catch (error) {
    console.error('Failed to start server:', error.message);
    process.exit(1);
  }
}

module.exports = { app, AppError };

# Security Improvements for app.js

## Executive Summary

The current `app.js` has several security weaknesses. This document outlines the improvements made and provides a guide for securing Express.js applications.

---

## Critical Security Issues Identified

### 1. **Missing Security Headers**
**Risk:** Vulnerable to various attacks including XSS, clickjacking, and MIME-sniffing.

**Solution Implemented:**
```javascript
app.use(helmet({
  contentSecurityPolicy: { /* ... */ },
  hsts: { /* ... */ },
}));
```

**Best Practice:** Use **helmet** middleware to set security HTTP headers:
- Content-Security-Policy (CSP)
- HTTP Strict Transport Security (HSTS)
- X-Content-Type-Options
- X-Frame-Options
- X-XSS-Protection

---

### 2. **No Rate Limiting**
**Risk:** Vulnerable to DoS/DDoS attacks and brute force attempts.

**Solution Implemented:**
```javascript
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000,
  max: 100,
});
app.use(limiter);

// Stricter for authentication routes
const authLimiter = rateLimit({
  windowMs: 15 * 60 * 1000,
  max: 5,
});
```

**Best Practice:** Implement rate limiting:
- Global limit for all endpoints
- Stricter limits for sensitive operations (auth, writes)
- Use sliding window for production

---

### 3. **Missing Input Validation**
**Risk:** SQL injection, XSS, command injection, and data corruption.

**Solution Implemented:**
```javascript
app.get('/users',
  [
    query('id').optional().isInt({ min: 1 }).toInt(),
    query('email').optional().isEmail().normalizeEmail(),
    query('name').optional().isLength({ min: 1, max: 100 }).trim().escape(),
  ],
  handleValidationErrors,
  // handler
);
```

**Best Practice:** Validate all inputs:
- Use **express-validator** for validation
- Validate type, format, length, and range
- Sanitize and normalize inputs
- Reject invalid requests with 400 status

---

### 4. **No Output Encoding / XSS Protection**
**Risk:** Cross-Site Scripting (XSS) attacks.

**Solution Implemented:**
```javascript
const sanitizeInput = (input) => {
  return sanitizeHtml(input, {
    allowedTags: [],
    allowedAttributes: {},
  });
};

app.use(sanitizeRequest); // Apply to all requests
```

**Best Practice:**
- Use **sanitize-html** or similar library
- Encode all user-generated content before output
- Implement Content-Security-Policy headers

---

### 5. **No Centralized Error Handling**
**Risk:** Information leakage, inconsistent responses, poor debugging.

**Solution Implemented:**
```javascript
// Custom error class
class AppError extends Error {
  constructor(message, statusCode, isOperational) {
    super(message);
    this.statusCode = statusCode;
    this.isOperational = isOperational;
  }
}

// Global error handler
app.use((err, req, res, next) => {
  const isDev = process.env.NODE_ENV !== 'production';
  res.status(err.statusCode || 500).json({
    error: isDev ? err.message : 'Internal server error',
    timestamp: new Date().toISOString(),
  });
});
```

**Best Practice:**
- Create custom error classes
- Use async handler wrapper to catch errors
- Don't leak stack traces in production
- Log all errors for monitoring

---

### 6. **Missing Request Body Size Limit**
**Risk:** Denial of service via large payloads (memory exhaustion).

**Solution Implemented:**
```javascript
app.use(express.json({ 
  limit: '10kb',
  strict: true,
}));
```

**Best Practice:** Set appropriate limits:
- JSON body: 10kb - 1mb depending on use case
- URL-encoded: 10kb - 1mb
- File uploads: Use separate limits

---

### 7. **No CORS Configuration**
**Risk:** Cross-origin requests from unauthorized domains.

**Recommendation (if needed):**
```javascript
const cors = require('cors');
app.use(cors({
  origin: process.env.ALLOWED_ORIGINS?.split(',') || ['https://yourdomain.com'],
  credentials: true,
  methods: ['GET', 'POST', 'PUT', 'DELETE'],
  allowedHeaders: ['Content-Type', 'Authorization'],
}));
```

---

### 8. **No Security Logging**
**Risk:** Unable to detect or investigate security incidents.

**Solution Implemented:**
```javascript
const logSecurityEvent = (eventType, details) => {
  console.error('[SECURITY]', JSON.stringify({
    timestamp: new Date().toISOString(),
    eventType,
    ...details,
  }));
};
```

**Best Practice:** Log security events:
- Failed authentication attempts
- Validation failures
- Rate limit violations
- 404 errors (potential scanning)
- Unexpected errors

---

## Additional Security Recommendations

### 9. **Environment Variable Management**
```javascript
// Validate required environment variables on startup
const validateConfig = () => {
  const required = ['DATABASE_URL', 'JWT_SECRET'];
  const missing = required.filter(v => !process.env[v]);
  if (missing.length > 0) {
    throw new Error(`Missing env vars: ${missing.join(', ')}`);
  }
};
```

### 10. **Authentication & Authorization**
```javascript
// JWT authentication middleware example
const authenticate = async (req, res, next) => {
  const token = req.headers.authorization?.split(' ')[1];

  if (!token) {
    return res.status(401).json({ error: 'Authentication required' });
  }

  try {
    const decoded = jwt.verify(token, process.env.JWT_SECRET);
    req.user = decoded;
    next();
  } catch (error) {
    res.status(401).json({ error: 'Invalid token' });
  }
};
```

### 11. **SQL Injection Protection**
```javascript
// Use parameterized queries (example with pg)
const getUsers = async (id) => {
  const result = await db.query(
    'SELECT * FROM users WHERE id = $1',
    [id]  // Parameterized - safe from injection
  );
  return result.rows;
};
```

### 12. **HTTPS Enforcement**
```javascript
app.use((req, res, next) => {
  if (req.secure || process.env.NODE_ENV === 'development') {
    next();
  } else {
    res.redirect(`https://${req.headers.host}${req.url}`);
  }
});
```

### 13. **Dependency Management**
```bash
# Regularly update dependencies and scan for vulnerabilities
npm audit
npm audit fix
npm update

# Consider using Snyk or Dependabot
```

---

## Required Dependencies

Add to your `package.json`:

```json
{
  "dependencies": {
    "express": "^4.18.2",
    "helmet": "^7.1.0",
    "express-rate-limit": "^7.1.5",
    "express-validator": "^7.0.1",
    "sanitize-html": "^2.11.0"
  }
}
```

Install with:
```bash
npm install helmet express-rate-limit express-validator sanitize-html
```

---

## Configuration Checklist

Create a `.env` file for configuration:

```bash
NODE_ENV=production
PORT=3000
ALLOWED_ORIGINS=https://yourdomain.com,https://api.yourdomain.com
JWT_SECRET=your-super-secret-key-use-environment-variable
DATABASE_URL=postgresql://user:pass@localhost:5432/dbname
LOG_LEVEL=info
RATE_LIMIT_WINDOW_MS=900000
RATE_LIMIT_MAX_REQUESTS=100
```

---

## Testing Recommendations

### 1. Input Validation Tests
```javascript
describe('User endpoints', () => {
  it('should reject invalid email', async () => {
    const res = await request(app)
      .post('/users')
      .send({ name: 'Test', email: 'invalid-email' });
    expect(res.status).toBe(400);
  });
});
```

### 2. Rate Limiting Tests
```javascript
it('should enforce rate limits', async () => {
  const promises = Array(101).fill().map(() => 
    request(app).get('/health')
  );
  const results = await Promise.all(promises);
  const rejected = results.filter(r => r.status === 429);
  expect(rejected.length).toBeGreaterThan(0);
});
```

### 3. Security Headers Tests
```javascript
it('should include security headers', async () => {
  const res = await request(app).get('/health');
  expect(res.headers['x-content-type-options']).toBe('nosniff');
  expect(res.headers['x-frame-options']).toBe('DENY');
});
```

---

## Security Testing Tools

Run these tools regularly:

```bash
# npm audit for vulnerabilities
npm audit

# Snyk for dependency scanning
npx snyk test

# OWASP ZAP for application scanning

# Burp Suite for penetration testing

# Custom security tests
npm run test:security
```

---

## Monitoring & Alerting

### Key Metrics to Monitor
1. Failed authentication attempts
2. Rate limit violations
3. Unusual error rates
4. Requests from suspicious IPs
5. Unexpected payload sizes

### Alert Thresholds
- >10 failed auth attempts per minute from same IP
- >500 rate limit violations per hour
- Error rate >5% of requests
- API response time >1s consistently

---

## Summary of Changes

| Area | Before | After |
|------|--------|-------|
| Security Headers | None | Helmet with CSP, HSTS |
| Rate Limiting | None | 100 req/15min, 5 req/15min for auth |
| Input Validation | None | express-validator on all routes |
| XSS Protection | None | sanitize-html middleware |
| Error Handling | None | Centralized with custom error class |
| Request Size | Unlimited | 10kb limit |
| Logging | Minimal | Security event logging |
| Config Validation | None | Startup validation |

---

## Next Steps

1. **Install dependencies**
   ```bash
   npm install helmet express-rate-limit express-validator sanitize-html
   ```

2. **Review and customize** the improved code for your specific needs

3. **Set up environment variables** in your deployment

4. **Implement authentication** if your application handles users

5. **Add database integration** with proper parameterized queries

6. **Set up monitoring** and alerting for security events

7. **Run security tests** before deploying to production

8. **Document your API** with OpenAPI/Swagger specs

---

