const { body, query, param, validationResult } = require('express-validator');

// Validation middleware factory
const validateRequest = (req, res, next) => {
  const errors = validationResult(req);
  if (!errors.isEmpty()) {
    return res.status(400).json({ 
      error: 'Validation failed', 
      details: errors.array() 
    });
  }
  next();
};
```

Apply to routes:
```javascript
app.get('/users', 
  query('limit').optional().isInt({ min: 1, max: 100 }),
  query('offset').optional().isInt({ min: 0 }),
  validateRequest,
  (req, res) => {
    const { limit = 10, offset = 0 } = req.query;
    // Return filtered/paginated results
  }
);
```

### 2. **Global Error Handling Middleware**

**Add comprehensive error handling:**
```javascript
// 404 handler - MUST be last route
app.use((req, res, next) => {
  res.status(404).json({ 
    error: 'Not Found',
    path: req.path,
    method: req.method
  });
});

// Global error handler - MUST be last middleware
app.use((err, req, res, next) => {
  // Log full error for debugging (server-side only)
  console.error('Error:', {
    message: err.message,
    stack: process.env.NODE_ENV === 'development' ? err.stack : undefined,
    url: req.url,
    method: req.method,
    ip: req.ip,
    timestamp: new Date().toISOString()
  });

  // Don't leak sensitive information in production
  const isDevelopment = process.env.NODE_ENV === 'development';

  res.status(err.status || 500).json({
    error: isDevelopment ? err.message : 'Internal Server Error',
    ...(isDevelopment && { stack: err.stack })
  });
});
```

### 3. **Security Headers**

**Add Helmet for security headers:**
```javascript
const helmet = require('helmet');

app.use(helmet({
  contentSecurityPolicy: {
    directives: {
      defaultSrc: ["'self'"],
      scriptSrc: ["'self'"],
      styleSrc: ["'self'"],
      imgSrc: ["'self'", "data:"]
    }
  },
  hsts: {
    maxAge: 31536000,
    includeSubDomains: true,
    preload: true
  }
}));
```

### 4. **Request Rate Limiting**

**Prevent DoS attacks:**
```javascript
const rateLimit = require('express-rate-limit');

const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // Limit each IP to 100 requests per windowMs
  message: { error: 'Too many requests, please try again later' },
  standardHeaders: true,
  legacyHeaders: false,
});

// Apply to all routes
app.use(limiter);

// Stricter limiter for sensitive endpoints
const authLimiter = rateLimit({
  windowMs: 15 * 60 * 1000,
  max: 5,
  message: { error: 'Too many authentication attempts' }
});
```

### 5. **Request Body Parsing & Size Limits**

**安全的请求解析：**
```javascript
app.use(express.json({ 
  limit: '1mb',  // Prevent large payload attacks
  strict: true   // Only accept objects and arrays
}));

app.use(express.urlencoded({ 
  extended: false,  // Use querystring library (more secure)
  limit: '1mb'
}));
```

### 6. **Input Sanitization**

**Prevent XSS and injection attacks:**
```javascript
const { sanitize } = require('express-validator');

// Sanitize middleware
app.use((req, res, next) => {
  if (req.body) {
    req.body = sanitizeBody(req.body);
  }
  if (req.query) {
    req.query = sanitizeBody(req.query);
  }
  next();
});

function sanitizeBody(obj) {
  if (typeof obj !== 'object' || obj === null) return obj;

  const sanitized = {};
  for (const [key, value] of Object.entries(obj)) {
    if (typeof value === 'string') {
      // Remove potentially dangerous characters
      sanitized[key] = value
        .replace(/[<>]/g, '')  // Basic XSS prevention
        .trim();
    } else if (typeof value === 'object') {
      sanitized[key] = sanitizeBody(value);
    } else {
      sanitized[key] = value;
    }
  }
  return sanitized;
}
```

### 7. ** Logging & Monitoring**

```javascript
const morgan = require('morgan');
