/**
 * Secure Environment Variable Configuration
 * 
 * This module validates required environment variables at startup
 * and prevents the application from running with missing or invalid config.
 */

/**
 * Validate boolean environment variable
 */
const parseBoolean = (value) => {
  if (value === 'true' || value === '1') return true;
  if (value === 'false' || value === '0') return false;
  return undefined;
};

/**
 * Validate integer environment variable
 */
const parseInteger = (value, min, max) => {
  const parsed = parseInt(value, 10);
  if (isNaN(parsed)) return undefined;
  if (min !== undefined && parsed < min) return undefined;
  if (max !== undefined && parsed > max) return undefined;
  return parsed;
};

/**
 * Validate port number
 */
const parsePort = (value) => {
  return parseInteger(value, 1, 65535);
};

/**
 * Configuration schema
 */
const configSchema = {
  // Required
  required: {
    NODE_ENV: {
      validator: (value) => ['development', 'production', 'test'].includes(value),
      errorMessage: 'NODE_ENV must be one of: development, production, test',
    },
  },

  // Optional with defaults
  optional: {
    PORT: {
      validator: parsePort,
      default: 3000,
      errorMessage: 'PORT must be a valid port number (1-65535)',
    },

    // Optional - not currently used but defined for future use
    DATABASE_URL: {
      validator: (value) => typeof value === 'string' && value.length > 0,
      default: undefined,
      errorMessage: 'DATABASE_URL must be a valid connection string',
    },
    AWS_ACCESS_KEY_ID: {
      validator: (value) => typeof value === 'string' && value.length > 20,
      default: undefined,
      errorMessage: 'AWS_ACCESS_KEY_ID must be a valid AWS access key',
    },
    AWS_SECRET_ACCESS_KEY: {
      validator: (value) => typeof value === 'string' && value.length > 20,
      default: undefined,
      errorMessage: 'AWS_SECRET_ACCESS_KEY must be a valid AWS secret key',
    },
    ANTHROPIC_API_KEY: {
      validator: (value) => typeof value === 'string' && value.startsWith('sk-ant-'),
      default: undefined,
      errorMessage: 'ANTHROPIC_API_KEY must be a valid Anthropic API key',
    },
    STRIPE_SECRET_KEY: {
      validator: (value) => typeof value === 'string' && value.startsWith('sk_'),
      default: undefined,
      errorMessage: 'STRIPE_SECRET_KEY must be a valid Stripe secret key',
    },
    LOGFIRE_TOKEN: {
      validator: (value) => typeof value === 'string' && value.length > 0,
      default: undefined,
      errorMessage: 'LOGFIRE_TOKEN must be a valid token',
    },
  },
};

/**
 * Validate environment variables
 * @throws {Error} If required variables are missing or invalid
 */
function validateEnvironment() {
  const errors = [];
  const config = {};
  const warnings = [];

  // Validate required variables
  for (const [key, schema] of Object.entries(configSchema.required)) {
    const value = process.env[key];

    if (value === undefined || value === '') {
      errors.push(`Required environment variable '${key}' is not set`);
      continue;
    }

    if (schema.validator && !schema.validator(value)) {
      errors.push(`${key}: ${schema.errorMessage}`);
      continue;
    }

    config[key] = value;
  }

  // Validate optional variables
  for (const [key, schema] of Object.entries(configSchema.optional)) {
    const value = process.env[key];

    if (value === undefined || value === '') {
      if (schema.default !== undefined) {
        config[key] = schema.default;
      }
      continue;
    }

    if (schema.validator && !schema.validator(value)) {
      warnings.push(`${key}: ${schema.errorMessage}`);
      continue;
    }

    config[key] = value;
  }

  // Report warnings (don't fail on optional vars)
  if (warnings.length > 0) {
    console.warn('Environment configuration warnings:');
    warnings.forEach(w => console.warn(`  - ${w}`));
  }

  // Fail on required variables
  if (errors.length > 0) {
    console.error('Environment configuration errors:');
    errors.forEach(e => console.error(`  - ${e}`));
    throw new Error(`Invalid environment configuration. ${errors.length} error(s) found.`);
  }

  // Return validated and typed config
  return {
    ...config,
    // Convenience accessors
    isDevelopment: config.NODE_ENV === 'development',
    isProduction: config.NODE_ENV === 'production',
    isTest: config.NODE_ENV === 'test',
    port: config.PORT,
  };
}

/**
 * Load and validate environment configuration
 */
let _config = null;

function getConfig() {
  if (_config === null) {
    _config = validateEnvironment();
  }
  return _config;
}

/**
 * Reload configuration (useful for testing)
 */
function reloadConfig() {
  _config = null;
  return getConfig();
}

/**
 * Get safe config for logging (excludes sensitive values)
 */
function getSafeConfig() {
  const config = getConfig();
  const safe = { ...config };

  // Redact sensitive values
  const sensitiveKeys = [
    'DATABASE_URL',
    'AWS_ACCESS_KEY_ID',
    'AWS_SECRET_ACCESS_KEY',
    'ANTHROPIC_API_KEY',
    'STRIPE_SECRET_KEY',
    'LOGFIRE_TOKEN',
    'SESSION_SECRET',
    'JWT_SECRET',
  ];

  for (const key of sensitiveKeys) {
    if (safe[key]) {
      safe[key] = '[REDACTED]';
    }
  }

  return safe;
}

// Auto-validate on module load in production
if (process.env.NODE_ENV === 'production') {
  try {
    getConfig();
  } catch (error) {
    console.error('CRITICAL: Failed to validate environment:', error.message);
    process.exit(1);
  }
}

module.exports = {
  getConfig,
  reloadConfig,
  getSafeConfig,
  validateEnvironment,
};

