const express = require('express');
const helmet = require('helmet');
const rateLimit = require('express-rate-limit');
const { body, param, query, validationResult } = require('express-validator');
const sanitizeHtml = require('sanitize-html');
const { createLogger, transports, format } = require('winston');

const app = express();
const logger = createLogger({
  level: 'info',
  format: format.combine(
    format.timestamp(),
    format.json()
  ),
  transports: [
    new transports.Console(),
    new transports.File({ filename: 'logs/error.log', level: 'error' }),
    new transports.File({ filename: 'logs/combined.log' })
  ]
});

// Security Middleware
app.use(helmet({
  contentSecurityPolicy: {
    directives: {
      defaultSrc: ["'self'"],
      scriptSrc: ["'self'"],
      styleSrc: ["'self'"],
    }
  },
  hsts: {
    maxAge: 31536000,
    includeSubDomains: true,
    preload: true
  }
}));

app.use(express.json({ limit: '10kb' })); // Limit body size to prevent DoS
app.use(express.urlencoded({ extended: true, limit: '10kb' }));

// Rate Limiting
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // Limit each IP to 100 requests per windowMs
  message: { error: 'Too many requests, please try again later.' },
  standardHeaders: true,
  legacyHeaders: false,
});

const strictLimiter = rateLimit({
  windowMs: 15 * 60 * 1000,
  max: 5, // More restrictive for sensitive endpoints
  message: { error: 'Too many attempts, please try again later.' }
});

app.use('/api/', limiter);

// Middleware: Request Logging
app.use((req, res, next) => {
  logger.info({
    method: req.method,
    url: req.url,
    ip: req.ip,
    userAgent: req.get('user-agent')
  });
  next();
});

// Middleware: Input Sanitization
const sanitizeInput = (req, res, next) => {
  if (req.body) {
    for (const key in req.body) {
      if (typeof req.body[key] === 'string') {
        req.body[key] = sanitizeHtml(req.body[key], {
          allowedTags: [],
          allowedAttributes: {}
        }).trim();
      }
    }
  }
  if (req.query) {
    for (const key in req.query) {
      if (typeof req.query[key] === 'string') {
        req.query[key] = sanitizeHtml(req.query[key], {
          allowedTags: [],
          allowedAttributes: {}
        }).trim();
      }
    }
  }
  next();
};

app.use(sanitizeInput);

// Middleware: Validation Error Handler
const handleValidationErrors = (req, res, next) => {
  const errors = validationResult(req);
  if (!errors.isEmpty()) {
    logger.warn('Validation failed', {
      url: req.url,
      errors: errors.array()
    });
    return res.status(400).json({
      error: 'Validation failed',
      details: errors.array()
    });
  }
  next();
};

// Middleware: Global Error Handler
app.use((err, req, res, next) => {
  logger.error('Unhandled error', {
    error: err.message,
    stack: err.stack,
    url: req.url,
    method: req.method,
    ip: req.ip
  });

  // Don't leak error details in production
  const isDevelopment = process.env.NODE_ENV !== 'production';

  res.status(err.status || 500).json({
    error: isDevelopment ? err.message : 'Internal server error',
    ...(isDevelopment && { stack: err.stack })
  });
});

// Routes

app.get('/health', (req, res) => {
  try {
    res.json({ 
      status: 'ok', 
      timestamp: new Date().toISOString(),
      uptime: process.uptime()
    });
  } catch (error) {
    logger.error('Health check failed', { error: error.message });
    res.status(500).json({ error: 'Health check failed' });
  }
});

app.get('/users', 
  [
    query('page')
      .optional()
      .isInt({ min: 1 })
      .withMessage('Page must be a positive integer'),
    query('limit')
      .optional()
      .isInt({ min: 1, max: 100 })
      .withMessage('Limit must be between 1 and 100'),
    query('sort')
      .optional()
      .isIn(['name', 'email', 'id'])
      .withMessage('Sort must be one of: name, email, id'),
    handleValidationErrors
  ],
  (req, res) => {
    try {
      const users = [
        { id: 1, name: 'Alice', email: 'alice@example.com' },
        { id: 2, name: 'Bob', email: 'bob@example.com' },
      ];

      const { page = 1, limit = 10, sort = 'id' } = req.query;

      // Apply sorting
      const sortedUsers = [...users].sort((a, b) => {
        if (a[sort] < b[sort]) return -1;
        if (a[sort] > b[sort]) return 1;
        return 0;
      });

      // Apply pagination
      const startIndex = (page - 1) * limit;
      const paginatedUsers = sortedUsers.slice(startIndex, startIndex + parseInt(limit));

      res.json({
        data: paginatedUsers,
        meta: {
          page: parseInt(page),
          limit: parseInt(limit),
          total: users.length,
          totalPages: Math.ceil(users.length / limit)
        }
      });
    } catch (error) {
      logger.error('Failed to fetch users', { error: error.message });
      res.status(500).json({ 
        error: 'Failed to fetch users',
        requestId: req.id
      });
    }
  }
);

app.get('/users/:id',
  [
    param('id')
      .isInt({ min: 1 })
      .withMessage('User ID must be a positive integer'),
    handleValidationErrors
  ],
  (req, res) => {
    try {
      const users = [
        { id: 1, name: 'Alice', email: 'alice@example.com' },
        { id: 2, name: 'Bob', email: 'bob@example.com' },
      ];

      const user = users.find(u => u.id === parseInt(req.params.id));

      if (!user) {
        logger.warn('User not found', { userId: req.params.id, ip: req.ip });
        return res.status(404).json({ error: 'User not found' });
      }

      res.json({ data: user });
    } catch (error) {
      logger.error('Failed to fetch user', { 
        userId: req.params.id,
        error: error.message 
      });
      res.status(500).json({ 
        error: 'Failed to fetch user',
        requestId: req.id
      });
    }
  }
);

app.post('/users',
  strictLimiter, // Apply stricter rate limiting for POST
  [
    body('name')
      .trim()
      .notEmpty()
      .withMessage('Name is required')
      .isLength({ min: 2, max: 100 })
      .withMessage('Name must be between 2 and 100 characters')
      .matches(/^[a-zA-Z\s'-]+$/)
      .withMessage('Name contains invalid characters'),
    body('email')
      .trim()
      .notEmpty()
      .withMessage('Email is required')
      .isEmail()
      .withMessage('Invalid email format')
      .normalizeEmail(),
    handleValidationErrors
  ],
  (req, res) => {
    try {
      const { name, email } = req.body;

      const newUser = {
        id: Date.now(), // In production, use a proper ID generator
        name,
        email
      };

      logger.info('User created', { 
        userId: newUser.id, 
        email: email,
        ip: req.ip 
      });

      res.status(201).json({ 
        data: newUser,
        message: 'User created successfully'
      });
    } catch (error) {
      logger.error('Failed to create user', { error: error.message });
      res.status(500).json({ 
        error: 'Failed to create user',
        requestId: req.id
      });
    }
  }
);

// 404 Handler
app.use((req, res) => {
  logger.warn('Route not found', { 
    url: req.url, 
    method: req.method,
    ip: req.ip 
  });
  res.status(404).json({ error: 'Route not found' });
});

// Start server only if not in test mode
if (require.main === module) {
  const server = app.listen(3000, () => {
    logger.info('Server running on port 3000');
  });

  // Graceful shutdown
  const gracefulShutdown = (signal) => {
    logger.info(`${signal} received. Closing server gracefully...`);
    server.close(() => {
      logger.info('Server closed');
      process.exit(0);
    });

    // Force close after 10 seconds
    setTimeout(() => {
      logger.error('Forcing server shutdown...');
      process.exit(1);
    }, 10000);
  };

  process.on('SIGTERM', () => gracefulShutdown('SIGTERM'));
  process.on('SIGINT', () => gracefulShutdown('SIGINT'));
}

module.exports = app;

