  },
  "devDependencies": {
    "jest": "^29.7.0",
    "nodemon": "^3.0.2",
    "supertest": "^6.3.3"
  },
  "engines": {
    "node": ">=18.0.0"
  }
}

# Security Improvements for app.js

## Overview
This document outlines the security improvements and best practices applied to the original `app.js`.

---

## Critical Security Issues Found

### 1. ❌ No Security Headers
**Original:** No HTTP security headers configured.
**Risk:** Vulnerable to XSS, clickjacking, and other attacks.
**Solution:** Added `helmet` middleware with CSP, HSTS, and other security headers.

---

### 2. ❌ No Input Validation
**Original:** No validation of query parameters, route parameters, or request bodies.
**Risk:** SQL injection, XSS, prototype pollution, and injection attacks.
**Solution:** Implemented `express-validator` for all inputs.

---

### 3. ❌ No Input Sanitization
**Original:** User input directly passed through without sanitization.
**Risk:** Cross-site scripting (XSS), HTML injection.
**Solution:** Added `sanitize-html` middleware to strip HTML/JS from inputs.

---

### 4. ❌ No Rate Limiting
**Original:** Unlimited requests allowed from any IP.
**Risk:** DoS attacks, brute force attacks, API abuse.
**Solution:** Implemented `express-rate-limit` with different tiers for endpoints.

---

### 5. ❌ No Error Handling
**Original:** No global error handling middleware.
**Risk:** Stack traces leaked to users, inconsistent error responses.
**Solution:** Added comprehensive error handling middleware that logs securely and sanitizes output.

---

### 6. ❌ No Request Size Limits
**Original:** No limits on request body size.
**Risk:** DoS attacks via large payloads.
**Solution:** Set 10kb limits on JSON and URL-encoded bodies.

---

### 7. ❌ No Security Logging
**Original:** No logging of security-relevant events.
**Risk:** Inability to detect and investigate attacks.
**Solution:** Added Winston logger with error, warn, and info levels.

---

### 8. ❌ Unstructured JSON Responses
**Original:** Inconsistent response format.
**Risk:** Difficult to handle errors client-side.
**Solution:** Standardized response format with `data`, `meta`, and `error` fields.

---

## Improvements Implemented

### Security Middleware

```javascript
// Helmet for security headers
app.use(helmet({
  contentSecurityPolicy: { /* ... */ },
  hsts: { /* ... */ }
}));

// Request body size limits
app.use(express.json({ limit: '10kb' }));
app.use(express.urlencoded({ extended: true, limit: '10kb' }));
```

### Rate Limiting

```javascript
// General rate limiting: 100 requests per 15 minutes
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000,
  max: 100
});

// Stricter for sensitive endpoints: 5 requests per 15 minutes
const strictLimiter = rateLimit({ /* ... */ });
```

### Input Validation & Sanitization

```javascript
// Sanitize all incoming string data
const sanitizeInput = (req, res, next) => {
  // Strip HTML/JS from all string inputs
  next();
};

// Validate query parameters
app.get('/users', [
  query('page').optional().isInt({ min: 1 }),
  query('limit').optional().isInt({ min: 1, max: 100 }),
  handleValidationErrors
], handler);

// Validate route parameters
app.get('/users/:id', [
  param('id').isInt({ min: 1 }),
  handleValidationErrors
], handler);

// Validate request body
app.post('/users', [
  body('name')
    .trim()
    .notEmpty()
    .isLength({ min: 2, max: 100 })
    .matches(/^[a-zA-Z\s'-]+$/),
  body('email')
    .trim()
    .isEmail()
    .normalizeEmail(),
  handleValidationErrors
], handler);
```

### Error Handling

```javascript
// Global error handler
app.use((err, req, res, next) => {
  logger.error('Unhandled error', { /* ... */ });

  // Don't leak stack traces in production
  const isDevelopment = process.env.NODE_ENV !== 'production';

  res.status(err.status || 500).json({
    error: isDevelopment ? err.message : 'Internal server error',
    ...(isDevelopment && { stack: err.stack })
  });
});

// 404 handler
app.use((req, res) => {
  res.status(404).json({ error: 'Route not found' });
});
```

### Security Logging

```javascript
const logger = createLogger({
  level: 'info',
  format: format.combine(
    format.timestamp(),
    format.json()
  ),
  transports: [
    new transports.Console(),
    new transports.File({ filename: 'logs/error.log', level: 'error' }),
    new transports.File({ filename: 'logs/combined.log' })
  ]
});

// Log each request
app.use((req, res, next) => {
  logger.info({
    method: req.method,
    url: req.url,
    ip: req.ip,
    userAgent: req.get('user-agent')
  });
  next();
});
```

### Graceful Shutdown

```javascript
const gracefulShutdown = (signal) => {
  server.close(() => {
    logger.info('Server closed');
    process.exit(0);
  });

  setTimeout(() => {
    logger.error('Forcing server shutdown...');
    process.exit(1);
  }, 10000);
};

process.on('SIGTERM', () => gracefulShutdown('SIGTERM'));
process.on('SIGINT', () => gracefulShutdown('SIGINT'));
```

---

## Additional Recommendations

### 1. Authentication & Authorization
Implement authentication for protected routes:
```javascript
const authenticate = (req, res, next) => {
  // Verify JWT token or session
  next();
};

app.get('/api/users', authenticate, handler);
```

### 2. CORS Configuration
```javascript
const cors = require('cors');
app.use(cors({
  origin: process.env.ALLOWED_ORIGINS?.split(',') || [],
  credentials: true
}));
```

### 3. Request ID Tracking
```javascript
const requestId = require('express-request-id');
app.use(requestId());
```

### 4. Environment Variables
```bash
# .env
NODE_ENV=production
PORT=3000
ALLOWED_ORIGINS=https://example.com
LOG_LEVEL=info
```

### 5. Health Check Enhancement
```javascript
app.get('/health', async (req, res) => {
  const checks = {
    uptime: process.uptime(),
    timestamp: Date.now(),
    database: await checkDatabase(),
    redis: await checkRedis()
  };

  const isHealthy = Object.values(checks)
    .filter(c => typeof c === 'boolean')
    .every(Boolean);

  res.status(isHealthy ? 200 : 503).json(checks);
});
```

### 6. API Versioning
```javascript
app.use('/api/v1', v1Routes);
app.use('/api/v2', v2Routes);
```

---

## Security Checklist

