      const paginatedUsers = filteredUsers.slice(startIndex, endIndex);

      // Sanitize output
      const sanitizedUsers = paginatedUsers.map(sanitizeUserData);

      res.json({
        data: sanitizedUsers,
        pagination: {
          page,
          limit,
          total: filteredUsers.length,
          totalPages: Math.ceil(filteredUsers.length / limit)
        }
      });
    } catch (error) {
      next(error);
    }
  }
);

