/**
 * Secure version of app.js with essential error handling and input validation
 * No external dependencies required - uses only built-in Node.js and Express
 */

const express = require('express');

const app = express();

// ============================================
// SECURITY: Basic rate limiting (in-memory)
// ============================================

const requestCounts = new Map();

const simpleRateLimit = (req, res, next) => {
  const ip = req.ip || req.connection.remoteAddress;
  const now = Date.now();
  const windowMs = 15 * 60 * 1000; // 15 minutes
  const maxRequests = 100;

  if (!requestCounts.has(ip)) {
    requestCounts.set(ip, { count: 1, resetTime: now + windowMs });
    return next();
  }

  const record = requestCounts.get(ip);

  if (now > record.resetTime) {
    record.count = 1;
    record.resetTime = now + windowMs;
    return next();
  }

  if (record.count >= maxRequests) {
    return res.status(429).json({
      error: 'Too many requests',
      message: 'Please try again later'
    });
  }

  record.count++;
  next();
};

// Clean up old rate limit entries periodically
setInterval(() => {
  const now = Date.now();
  for (const [ip, record] of requestCounts.entries()) {
    if (now > record.resetTime) {
      requestCounts.delete(ip);
    }
  }
}, 5 * 60 * 1000); // Every 5 minutes

// ============================================
// SECURITY: Set basic security headers
// ============================================

app.use((req, res, next) => {
  // Prevent clickjacking
  res.setHeader('X-Frame-Options', 'DENY');
  // Prevent MIME-sniffing
  res.setHeader('X-Content-Type-Options', 'nosniff');
  // Enable XSS filter
  res.setHeader('X-XSS-Protection', '1; mode=block');
  // Referrer policy
  res.setHeader('Referrer-Policy', 'strict-origin-when-cross-origin');
  next();
});

// Apply rate limiting
app.use(simpleRateLimit);

// ============================================
// SECURITY: Input validation helpers
// ============================================

// Validate and sanitize query parameters
const validateQueryParams = (req, res, next) => {
  const errors = [];

  // Check for parameter pollution (duplicate parameters)
  if (Object.keys(req.query).length !== new Set(Object.keys(req.query)).size) {
    return res.status(400).json({
      error: 'Invalid request',
      message: 'Duplicate parameters detected'
    });
  }

  // Validate any query parameters are safe
  for (const [key, value] of Object.entries(req.query)) {
    if (typeof value !== 'string') {
      errors.push(`Parameter '${key}' must be a string`);
      continue;
    }

    // Trimming and length check
    const trimmed = value.trim();
    if (trimmed.length > 100) {
      errors.push(`Parameter '${key}' exceeds maximum length of 100 characters`);
      continue;
    }

    // Basic XSS prevention - check for script tags and event handlers
    const xssPatterns = [
      /<script/i,
      /javascript:/i,
      /on\w+\s*=/i,
      /<iframe/i,
      /<object/i,
      /<embed/i
    ];

    for (const pattern of xssPatterns) {
      if (pattern.test(trimmed)) {
        errors.push(`Parameter '${key}' contains invalid content`);
        break;
      }
    }
  }

  if (errors.length > 0) {
    return res.status(400).json({
      error: 'Validation failed',
      details: errors
    });
  }

  next();
};

// Sanitize output data
const sanitizeOutput = (data) => {
  const sanitized = Array.isArray(data) ? [] : {};

  for (const key in data) {
    if (data.hasOwnProperty(key)) {
      const value = data[key];

      if (typeof value === 'string') {
        // Remove potential HTML/XML tags and normalize
        sanitized[key] = value
          .trim()
          .replace(/[<>]/g, '')  // Remove angle brackets
          .replace(/&/g, '&amp;')  // Escape ampersands
          .replace(/"/g, '&quot;') // Escape quotes
          .replace(/'/g, '&#x27;');
      } else if (typeof value === 'object' && value !== null) {
        sanitized[key] = sanitizeOutput(value);
      } else {
        sanitized[key] = value;
      }
    }
  }

  return sanitized;
};

// ============================================
// ERROR HANDLING: Centralized error handler
// ============================================

// Async wrapper to catch errors in async route handlers
const asyncHandler = (fn) => {
  return (req, res, next) => {
    Promise.resolve(fn(req, res, next)).catch(next);
  };
};

// Global error handler (must be last)
const errorHandler = (err, req, res, next) => {
  // Log error (in production, use proper logging)
  console.error('Error occurred:', {
    message: err.message,
    stack: err.stack,
    path: req.path,
    method: req.method,
    ip: req.ip,
    timestamp: new Date().toISOString()
  });

  // Don't expose internal errors to clients
  const statusCode = err.statusCode || 500;
  const message = statusCode === 500 ? 'Internal Server Error' : err.message;

  res.status(statusCode).json({
    error: message,
    // Only include stack trace in development
    ...(process.env.NODE_ENV === 'development' && { stack: err.stack })
  });
};

// ============================================
// ROUTES: Improved with validation and error handling
// ============================================

// Health check endpoint
app.get('/health', asyncHandler(async (req, res) => {
  res.json({
    status: 'ok',
    timestamp: new Date().toISOString()
  });
}));

// Users endpoint with validation
app.get('/users', validateQueryParams, asyncHandler(async (req, res) => {
  // Support pagination with sanitized query params
  const page = Math.max(1, parseInt(req.query.page) || 1);
  const limit = Math.min(100, Math.max(1, parseInt(req.query.limit) || 10));

  // Mock users data
  const allUsers = [
    { id: 1, name: 'Alice', email: 'alice@example.com' },
    { id: 2, name: 'Bob', email: 'bob@example.com' },
  ];

  // Apply pagination
  const start = (page - 1) * limit;
  const users = allUsers.slice(start, start + limit);

  // Sanitize output before sending
  res.json({
    data: sanitizeOutput(users),
    pagination: {
      page,
      limit,
      total: allUsers.length
    }
  });
}));

// ============================================
// 404 Handler
// ============================================

app.use((req, res) => {
  res.status(404).json({
    error: 'Not Found',
    message: 'The requested resource was not found',
    path: req.path
  });
});

// ============================================
// ERROR HANDLER (must be last)
// ============================================

app.use(errorHandler);

// ============================================
// SERVER STARTUP
// ============================================

const PORT = 3000;  // Hardcoded - no env var needed

const server = app.listen(PORT, () => {
  console.log(`Server running on port ${PORT}`);
  console.log(`Environment: ${process.env.NODE_ENV || 'development'}`);
});

// ============================================
// GRACEFUL SHUTDOWN
// ============================================

const gracefulShutdown = (signal) => {
  console.log(`\n${signal} received. Shutting down gracefully...`);

  server.close(() => {
    console.log('Server closed');
    process.exit(0);
  });

  // Force shutdown after 10 seconds
  setTimeout(() => {
