const express = require('express');
const helmet = require('helmet');
const rateLimit = require('express-rate-limit');
const { body, query, param, validationResult } = require('express-validator');

const app = express();

// Security middleware
app.use(helmet());

// Rate limiting to prevent brute force attacks
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // Limit each IP to 100 requests per windowMs
  message: { error: 'Too many requests, please try again later.' },
  standardHeaders: true,
  legacyHeaders: false,
});
app.use(limiter);

// Stricter rate limiting for authentication endpoints
const authLimiter = rateLimit({
  windowMs: 15 * 60 * 1000,
  max: 5,
  message: { error: 'Too many login attempts, please try again later.' },
  skipSuccessfulRequests: true,
});

// Body parsing with size limits to prevent DoS
app.use(express.json({ limit: '10kb' }));
app.use(express.urlencoded({ extended: true, limit: '10kb' }));

// Custom middleware to handle validation errors
const handleValidationErrors = (req, res, next) => {
  const errors = validationResult(req);
  if (!errors.isEmpty()) {
    return res.status(400).json({
      error: 'Validation failed',
      details: errors.array().map(err => ({
        field: err.path || err.param,
        message: err.msg,
      })),
    });
  }
  next();
};

// Custom middleware for async error handling
const asyncHandler = (fn) => (req, res, next) => {
  Promise.resolve(fn(req, res, next)).catch(next);
};

// sanitization middleware to prevent injection attacks
const sanitizeInput = (req, res, next) => {
  if (req.body) {
    // Remove potentially dangerous characters from strings
    const sanitizeObject = (obj) => {
      if (typeof obj !== 'object' || obj === null) return obj;

      return Object.keys(obj).reduce((acc, key) => {
        const value = obj[key];
        if (typeof value === 'string') {
          // Remove null bytes and excessive whitespace
          acc[key] = value.replace(/\0/g, '').trim().substring(0, 1000);
        } else if (typeof value === 'object') {
          acc[key] = sanitizeObject(value);
        } else {
          acc[key] = value;
        }
        return acc;
      }, {});
    };
    req.body = sanitizeObject(req.body);
  }
  next();
};

app.use(sanitizeInput);

// Health check endpoint
app.get('/health', asyncHandler(async (req, res) => {
  try {
    res.json({ 
      status: 'ok', 
      timestamp: new Date().toISOString(),
      uptime: process.uptime()
    });
  } catch (error) {
    res.status(500).json({ 
      error: 'Internal server error',
      message: process.env.NODE_ENV === 'development' ? error.message : undefined
    });
  }
}));

// Users endpoint with query validation
app.get(
  '/users',
  [
    query('limit')
      .optional()
      .isInt({ min: 1, max: 100 })
      .withMessage('Limit must be an integer between 1 and 100')
      .toInt(),
    query('offset')
      .optional()
      .isInt({ min: 0 })
      .withMessage('Offset must be a non-negative integer')
      .toInt(),
    query('sort')
      .optional()
      .isIn(['id', 'name', 'email'])
      .withMessage('Sort must be one of: id, name, email'),
  ],
  handleValidationErrors,
  asyncHandler(async (req, res) => {
    try {
      const users = [
        { id: 1, name: 'Alice', email: 'alice@example.com' },
        { id: 2, name: 'Bob', email: 'bob@example.com' },
      ];

      // Apply pagination and sorting securely
      const { limit = 10, offset = 0, sort = 'id' } = req.query;

      const startIndex = Math.min(offset, users.length);
      const endIndex = Math.min(startIndex + limit, users.length);

      // Secure sorting - only allow predefined fields
      const sortedUsers = [...users].sort((a, b) => {
        if (a[sort] < b[sort]) return -1;
        if (a[sort] > b[sort]) return 1;
        return 0;
      });

      const paginatedUsers = sortedUsers.slice(startIndex, endIndex);

      res.json({
        data: paginatedUsers,
        meta: {
          total: users.length,
          limit,
          offset,
          hasMore: endIndex < users.length
        }
      });
    } catch (error) {
      console.error('Error in /users endpoint:', error);
      res.status(500).json({ 
        error: 'Failed to retrieve users' 
      });
    }
  })
);

// Example: Get user by ID with parameter validation
app.get(
  '/users/:id',
  [
    param('id')
      .isInt({ min: 1 })
      .withMessage('ID must be a positive integer')
      .toInt(),
  ],
  handleValidationErrors,
  asyncHandler(async (req, res) => {
    try {
      const { id } = req.params;

      const users = [
        { id: 1, name: 'Alice', email: 'alice@example.com' },
        { id: 2, name: 'Bob', email: 'bob@example.com' },
      ];

      const user = users.find(u => u.id === id);

      if (!user) {
        return res.status(404).json({ 
          error: 'User not found',
          userId: id
        });
      }

      res.json({ data: user });
    } catch (error) {
      console.error('Error in /users/:id endpoint:', error);
      res.status(500).json({ 
        error: 'Failed to retrieve user' 
      });
    }
  })
);

// Example: Create user with body validation
app.post(
  '/users',
  [
    body('name')
      .trim()
      .notEmpty()
      .withMessage('Name is required')
      .isLength({ min: 1, max: 100 })
      .withMessage('Name must be between 1 and 100 characters')
      .matches(/^[a-zA-Z\s'-]+$/)
      .withMessage('Name contains invalid characters'),
    body('email')
      .trim()
      .notEmpty()
      .withMessage('Email is required')
      .isEmail()
      .withMessage('Invalid email format')
      .normalizeEmail(),
    body('age')
      .optional()
      .isInt({ min: 0, max: 150 })
      .withMessage('Age must be between 0 and 150'),
  ],
  handleValidationErrors,
  authLimiter, // Rate limit for writes
  asyncHandler(async (req, res) => {
    try {
      const { name, email, age } = req.body;

      // Check for duplicate email (example of business logic validation)
      const existingUsers = [
        { id: 1, name: 'Alice', email: 'alice@example.com' },
        { id: 2, name: 'Bob', email: 'bob@example.com' },
      ];

      const emailExists = existingUsers.some(u => u.email.toLowerCase() === email.toLowerCase());
      if (emailExists) {
        return res.status(409).json({ 
          error: 'Email already exists',
          field: 'email'
        });
      }

      // Create new user
      const newUser = {
        id: existingUsers.length + 1,
        name,
        email,
        age: age || null,
      };

      res.status(201).json({ 
        message: 'User created successfully',
        data: newUser
      });
    } catch (error) {
      console.error('Error in POST /users endpoint:', error);
      res.status(500).json({ 
        error: 'Failed to create user' 
      });
    }
  })
);

// 404 handler - must be after all routes
app.use((req, res) => {
  res.status(404).json({ 
    error: 'Not found',
    path: req.path,
    method: req.method
  });
});

// Global error handler - must be last
app.use((err, req, res, next) => {
  console.error('Unhandled error:', err);

  // Don't leak stack traces in production
  const isDevelopment = process.env.NODE_ENV === 'development';

  res.status(err.status || 500).json({
    error: isDevelopment ? err.message : 'Internal server error',
    ...(isDevelopment && { stack: err.stack }),
  });
});

// Start server
const PORT = process.env.PORT || 3000;

const server = app.listen(PORT, () => {
  console.log(`Server running on port ${PORT}`);
  console.log(`Environment: ${process.env.NODE_ENV || 'development'}`);
});

// Graceful shutdown
process.on('SIGTERM', () => {
  console.log('SIGTERM signal received: closing HTTP server');
  server.close(() => {
    console.log('HTTP server closed');
    process.exit(0);
  });
});

process.on('unhandledRejection', (reason, promise) => {
  console.error('Unhandled Rejection at:', promise, 'reason:', reason);
});

process.on('uncaughtException', (error) => {
  console.error('Uncaught Exception:', error);
  process.exit(1);
});

module.exports = app;

