        name: 'Test', 
        email: 'invalid-email',
        age: 25
      });

    expect(response.status).toBe(400);
    expect(response.body.details).toBeDefined();
  });
});
```

### 2. **Load Testing**

Use tools like Artillery or Apache Bench:
```bash
# Install artillery
npm install -g artillery

# Create load test
artillery quick --count 100 --num 10 http://localhost:3000/health
```

