// Improved application with security best practices, error handling, and input validation
// This version addresses security vulnerabilities and follows best practices

const express = require('express');
const helmet = require('helmet');
const rateLimit = require('express-rate-limit');
const { body, query, validationResult } = require('express-validator');

const app = express();

// SECURITY MIDDLEWARE

// 1. Helmet: Sets secure HTTP headers
app.use(helmet({
  contentSecurityPolicy: {
    directives: {
      defaultSrc: ["'self'"],
      styleSrc: ["'self'", "'unsafe-inline'"],
      scriptSrc: ["'self'"],
      imgSrc: ["'self'", "data:", "https:"]
    }
  },
  hsts: {
    maxAge: 31536000,
    includeSubDomains: true,
    preload: true
  }
}));

// 2. Rate limiting: Prevents DoS attacks and brute force
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // Limit each IP to 100 requests per windowMs
  message: 'Too many requests from this IP, please try again later.',
  standardHeaders: true,
  legacyHeaders: false
});

// Stricter rate limiting for user data endpoints
const strictLimiter = rateLimit({
  windowMs: 15 * 60 * 1000,
  max: 30,
  message: 'Too many requests from this IP, please try again later.'
});

app.use(limiter);
app.use(express.json({ limit: '10mb' })); // Parse JSON with size limit

// 3. Body parser with size limits to prevent payload overflow attacks
app.use(express.urlencoded({ 
  extended: true, 
  limit: '10mb' 
}));

// REQUEST VALIDATION MIDDLEWARE

// Middleware to check validation results
const validateRequest = (req, res, next) => {
  const errors = validationResult(req);
  if (!errors.isEmpty()) {
    return res.status(400).json({
      error: 'Validation failed',
      details: errors.array()
    });
  }
  next();
};

// ERROR HANDLING MIDDLEWARE

// Global error handler (must be last)
app.use((err, req, res, next) => {
  console.error('Error:', {
    message: err.message,
    stack: process.env.NODE_ENV === 'production' ? undefined : err.stack,
    timestamp: new Date().toISOString(),
    path: req.path,
    method: req.method,
    ip: req.ip
  });

  // Don't leak sensitive error details in production
  const statusCode = err.statusCode || 500;
  const message = process.env.NODE_ENV === 'production' 
    ? 'An error occurred' 
    : err.message;

  res.status(statusCode).json({
    error: message,
    ...(process.env.NODE_ENV !== 'production' && { stack: err.stack })
  });
});

// 404 handler (must be after all routes but before error handler)
app.use((req, res) => {
  res.status(404).json({
    error: 'Not Found',
    message: `Cannot ${req.method} ${req.path}`
  });
});

// SANITIZATION HELPERS

// Sanitize output data (remove sensitive fields)
const sanitizeUser = (user) => {
  const { password, ...sanitized } = user;
  return sanitized;
};

// ROUTES

// Health check with optional status query parameter validation
app.get('/health', 
  [
    query('status', 'if provided, must be "full" or "basic"')
      .optional()
      .isIn(['full', 'basic'])
  ],
  validateRequest,
  (req, res) => {
    const statusLevel = req.query.status || 'basic';

    const healthData = {
      status: 'ok',
      timestamp: new Date().toISOString()
    };

    if (statusLevel === 'full') {
      healthData.version = process.env.APP_VERSION || '1.0.0';
      healthData.environment = process.env.NODE_ENV || 'development';
    }

    res.json(healthData);
  }
);

// Get users with pagination and filtering
app.get('/users',
  strictLimiter,
  [
    query('page', 'Page must be a positive integer')
      .optional()
      .isInt({ min: 1 })
      .toInt(),
    query('limit', 'Limit must be between 1 and 100')
      .optional()
      .isInt({ min: 1, max: 100 })
      .toInt(),
    query('search', 'Search must be a string with max 100 characters')
      .optional()
      .isString()
      .trim()
      .isLength({ max: 100 })
      .escape()
  ],
  validateRequest,
  (req, res) => {
    try {
      const page = req.query.page || 1;
      const limit = req.query.limit || 10;
      const search = req.query.search;

      // Mock user data (in real app, this would come from database)
      const allUsers = [
        { id: 1, name: 'Alice', email: 'alice@example.com', role: 'user' },
        { id: 2, name: 'Bob', email: 'bob@example.com', role: 'user' },
        { id: 3, name: 'Charlie', email: 'charlie@example.com', role: 'admin' }
      ];

      // Apply search filter if provided
      let filteredUsers = allUsers;
      if (search) {
        const searchLower = search.toLowerCase();
        filteredUsers = allUsers.filter(user => 
          user.name.toLowerCase().includes(searchLower) ||
          user.email.toLowerCase().includes(searchLower)
        );
      }

      // Calculate pagination
      const startIndex = (page - 1) * limit;
      const endIndex = startIndex + limit;
      const paginatedUsers = filteredUsers.slice(startIndex, endIndex);

      // Sanitize user data before sending
      const sanitizedUsers = paginatedUsers.map(sanitizeUser);

      res.json({
        data: sanitizedUsers,
        pagination: {
          page,
          limit,
          total: filteredUsers.length,
          totalPages: Math.ceil(filteredUsers.length / limit)
        }
      });
    } catch (error) {
      // Pass to global error handler
      next(error);
    }
  }
);

// Get single user by ID
app.get('/users/:id',
  strictLimiter,
  [
    // This would be handled by express-validator or a similar library for params
  ],
  (req, res, next) => {
    try {
      // Validate ID is a number and positive
      const userId = parseInt(req.params.id, 10);

      if (isNaN(userId) || userId <= 0) {
        return res.status(400).json({
          error: 'Invalid user ID',
          message: 'User ID must be a positive integer'
        });
      }

      // Mock users
      const users = [
        { id: 1, name: 'Alice', email: 'alice@example.com', role: 'user' },
        { id: 2, name: 'Bob', email: 'bob@example.com', role: 'user' }
      ];

      const user = users.find(u => u.id === userId);

      if (!user) {
        return res.status(404).json({
          error: 'Not Found',
          message: `User with ID ${userId} not found`
        });
      }

      res.json(sanitizeUser(user));
    } catch (error) {
      next(error);
    }
  }
);

// SECURITY HEADERS ENDPOINT (for testing)
app.get('/security-headers', (req, res) => {
  res.json({
    message: 'Security headers are properly configured',
    headers: res.getHeaders()
  });
});

// SERVER STARTUP

// Don't run server if this file is imported
if (require.main === module) {
  const PORT = process.env.PORT || 3000;

  const server = app.listen(PORT, () => {
    console.log(`Server running on port ${PORT}`);
    console.log(`Environment: ${process.env.NODE_ENV || 'development'}`);
    console.log('Security features enabled: Helmet, Rate Limiting, Input Validation');
  });

  // Graceful shutdown
  const gracefulShutdown = (signal) => {
    console.log(`\n${signal} received. Starting graceful shutdown...`);

    server.close(() => {
      console.log('Server closed');
      process.exit(0);
    });

    // Force shutdown after 10 seconds
    setTimeout(() => {
      console.error('Forced shutdown after timeout');
      process.exit(1);
    }, 10000);
  };

  process.on('SIGTERM', () => gracefulShutdown('SIGTERM'));
  process.on('SIGINT', () => gracefulShutdown('SIGINT'));

  // Handle uncaught exceptions
  process.on('uncaughtException', (err) => {
    console.error('Uncaught Exception:', err);
    gracefulShutdown('uncaughtException');
  });

  process.on('unhandledRejection', (reason, promise) => {
    console.error('Unhandled Rejection at:', promise, 'reason:', reason);
    gracefulShutdown('unhandledRejection');
  });
}

module.exports = app;

