const express = require('express');
const helmet = require('helmet');
const rateLimit = require('express-rate-limit');
const { body, query, param, validationResult } = require('express-validator');

const app = express();

// ============================================================================
// SECURITY MIDDLEWARE
// ============================================================================

// Security headers
app.use(helmet({
  contentSecurityPolicy: {
    directives: {
      defaultSrc: ["'self'"],
      styleSrc: ["'self'", "'unsafe-inline'"],
      scriptSrc: ["'self'"],
    },
  },
  hsts: {
    maxAge: 31536000,
    includeSubDomains: true,
    preload: true,
  },
}));

// Rate limiting to prevent brute force and DoS attacks
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // limit each IP to 100 requests per windowMs
  message: { error: 'Too many requests, please try again later.' },
  standardHeaders: true,
  legacyHeaders: false,
});

app.use('/api/', limiter);

// Body parser with size limits to prevent DoS
app.use(express.json({
  limit: '10kb',
  strict: true,
}));

app.use(express.urlencoded({
  extended: false,
  limit: '10kb',
}));

// ============================================================================
// VALIDATION MIDDLEWARE
// ============================================================================

// Middleware to handle validation errors
const handleValidationErrors = (req, res, next) => {
  const errors = validationResult(req);
  if (!errors.isEmpty()) {
    return res.status(400).json({
      error: 'Validation failed',
      details: errors.array().map(err => ({
        field: err.path,
        message: err.msg,
        value: err.value,
      })),
    });
  }
  next();
};

// Async error wrapper to catch errors in async route handlers
const asyncHandler = (fn) => (req, res, next) => {
  Promise.resolve(fn(req, res, next)).catch(next);
};

// ============================================================================
// INPUT SANITIZATION UTILITIES
// ============================================================================

// Sanitize user input to prevent XSS and injection attacks
const sanitizeInput = (input) => {
  if (typeof input !== 'string') return input;
  return input
    .replace(/[<>]/g, '') // Remove potential HTML tags
    .trim();
};

const sanitizeObj = (obj) => {
  if (!obj || typeof obj !== 'object') return obj;

  const sanitized = {};
  for (const [key, value] of Object.entries(obj)) {
    if (typeof value === 'string') {
      sanitized[key] = sanitizeInput(value);
    } else if (Array.isArray(value)) {
      sanitized[key] = value.map(item => 
        typeof item === 'string' ? sanitizeInput(item) : item
      );
    } else if (typeof value === 'object' && value !== null) {
      sanitized[key] = sanitizeObj(value);
    } else {
      sanitized[key] = value;
    }
  }
  return sanitized;
};

// ============================================================================
// ROUTES WITH VALIDATION AND ERROR HANDLING
// ============================================================================

// Health check endpoint
app.get('/health', asyncHandler(async (req, res) => {
  // Validate query parameters if any
  await query('verbose')
    .optional()
    .isIn(['true', 'false', '1', '0'])
    .withMessage('verbose must be a boolean value')
    .run(req);

  handleValidationErrors(req, res, () => {});

  const verbose = req.query.verbose === 'true' || req.query.verbose === '1';

  const healthData = {
    status: 'ok',
    timestamp: new Date().toISOString(),
  };

  if (verbose && process.env.NODE_ENV !== 'production') {
    healthData.uptime = process.uptime();
    healthData.environment = process.env.NODE_ENV || 'development';
  }

  res.json(healthData);
}));

// Get users with pagination and filtering
app.get('/users', [
  // Validate query parameters
  query('page')
    .optional()
    .isInt({ min: 1 })
    .withMessage('page must be a positive integer')
    .toInt(),
  query('limit')
    .optional()
    .isInt({ min: 1, max: 100 })
    .withMessage('limit must be between 1 and 100')
    .toInt(),
  query('search')
    .optional()
    .trim()
    .isLength({ min: 1, max: 50 })
    .withMessage('search term must be between 1 and 50 characters')
    .escape(),
], handleValidationErrors, asyncHandler(async (req, res) => {
  // Get validated query parameters with defaults
  const page = req.query.page || 1;
  const limit = req.query.limit || 10;
  const search = req.query.search;

  // Simulated user data (in production, this would come from a database)
  const allUsers = [
    { id: 1, name: 'Alice', email: 'alice@example.com' },
    { id: 2, name: 'Bob', email: 'bob@example.com' },
    { id: 3, name: 'Charlie', email: 'charlie@example.com' },
  ];

  // Filter users if search term provided
  let filteredUsers = allUsers;
  if (search) {
    const searchTerm = search.toLowerCase();
    filteredUsers = allUsers.filter(user => 
      user.name.toLowerCase().includes(searchTerm) ||
      user.email.toLowerCase().includes(searchTerm)
    );
  }

  // Pagination
  const startIndex = (page - 1) * limit;
  const endIndex = startIndex + limit;
  const paginatedUsers = filteredUsers.slice(startIndex, endIndex);

  res.json({
    data: paginatedUsers,
    pagination: {
      page,
      limit,
      total: filteredUsers.length,
      totalPages: Math.ceil(filteredUsers.length / limit),
    },
  });
}));

// Get single user by ID
app.get('/users/:id', [
  param('id')
    .isInt({ min: 1 })
    .withMessage('id must be a positive integer')
    .toInt(),
], handleValidationErrors, asyncHandler(async (req, res) => {
  const userId = req.params.id;

  // Simulated user lookup (in production, this would query a database)
  const user = {
    id: userId,
    name: 'Alice',
    email: 'alice@example.com',
  };

  if (!user) {
    return res.status(404).json({
      error: 'User not found',
      details: `No user exists with id: ${userId}`,
    });
  }

  res.json(user);
}));

// Create new user (example of POST with validation)
app.post('/users', [
  body('name')
    .trim()
    .isLength({ min: 2, max: 100 })
    .withMessage('name must be between 2 and 100 characters')
    .matches(/^[a-zA-Z\s'-]+$/)
    .withMessage('name contains invalid characters'),
  body('email')
    .trim()
    .isEmail()
    .normalizeEmail()
    .withMessage('email must be a valid email address'),
], handleValidationErrors, asyncHandler(async (req, res) => {
  // Sanitize input
  const sanitizedData = sanitizeObj(req.body);

  // Simulated user creation (in production, this would insert into a database)
  const newUser = {
    id: Date.now(), // Not recommended for production - use proper IDs
    ...sanitizedData,
    createdAt: new Date().toISOString(),
  };

  // Log user creation (without sensitive data in production)
  if (process.env.NODE_ENV !== 'production') {
    console.log(`User created: ${newUser.id}`);
  }

  res.status(201).json({
    message: 'User created successfully',
    data: {
      id: newUser.id,
      name: newUser.name,
      email: newUser.email,
      createdAt: newUser.createdAt,
    },
  });
}));

// ============================================================================
// ERROR HANDLING MIDDLEWARE (Must be last)
// ============================================================================

// 404 handler - must be after all routes
app.use((req, res) => {
  res.status(404).json({
    error: 'Not Found',
    message: `Cannot ${req.method} ${req.path}`,
    timestamp: new Date().toISOString(),
  });
});

// Global error handler
app.use((err, req, res, next) => {
  // Log error for debugging (in production, use proper logging service)
  console.error('[Error]', {
    message: err.message,
    stack: process.env.NODE_ENV === 'development' ? err.stack : undefined,
    url: req.url,
    method: req.method,
    ip: req.ip,
    timestamp: new Date().toISOString(),
  });

  // Determine status code
  const statusCode = err.statusCode || err.status || 500;

  // Create error response
  const errorResponse = {
    error: statusCode === 500 ? 'Internal Server Error' : err.message,
    timestamp: new Date().toISOString(),
  };

  // Include stack trace only in development
  if (process.env.NODE_ENV === 'development') {
    errorResponse.stack = err.stack;
    errorResponse.details = err.details || null;
  }

  // Handle specific error types
  if (err.name === 'UnauthorizedError') {
    return res.status(401).json({
      ...errorResponse,
      error: 'Unauthorized',
    });
  }

  if (err.type === 'entity.parse.failed') {
    return res.status(400).json({
      ...errorResponse,
      error: 'Invalid JSON',
    });
  }

  res.status(statusCode).json(errorResponse);
});

// ============================================================================
// SERVER STARTUP
// ============================================================================

const PORT = process.env.PORT || 3000;

// Only start server if this file is run directly
if (require.main === module) {
  const server = app.listen(PORT, () => {
    // Secure logging - don't expose sensitive info
    console.log(`Server running on port ${PORT} in ${process.env.NODE_ENV || 'development'} mode`);
  });

  // Graceful shutdown
  const gracefulShutdown = (signal) => {
    console.log(`\n${signal} received. Starting graceful shutdown...`);
    server.close(() => {
      console.log('Server closed successfully');
      process.exit(0);
    });

    // Force shutdown after 10 seconds
    setTimeout(() => {
      console.error('Forced shutdown after timeout');
      process.exit(1);
    }, 10000);
  };

  process.on('SIGTERM', () => gracefulShutdown('SIGTERM'));
  process.on('SIGINT', () => gracefulShutdown('SIGINT'));

  // Handle uncaught exceptions
  process.on('uncaughtException', (err) => {
    console.error('Uncaught Exception:', err);
    gracefulShutdown('uncaughtException');
  });

  // Handle unhandled promise rejections
  process.on('unhandledRejection', (reason, promise) => {
    console.error('Unhandled Rejection at:', promise, 'reason:', reason);
    gracefulShutdown('unhandledRejection');
  });
}

module.exports = app;

