input.content:
// Improved application with security best practices
// Error handling, input validation, and security headers

const express = require('express');
const helmet = require('helmet');
const rateLimit = require('express-rate-limit');
const { body, query, param, validationResult } = require('express-validator');

const app = express();

// ============================================
// SECURITY MIDDLEWARE
// ============================================

// Security headers with Helmet
app.use(helmet({
  contentSecurityPolicy: {
    directives: {
      defaultSrc: ["'self'"],
      scriptSrc: ["'self'"],
      styleSrc: ["'self'"],
      imgSrc: ["'self'", "data:"],
    },
  },
  hsts: {
    maxAge: 31536000,
    includeSubDomains: true,
    preload: true,
  },
}));

// Rate limiting to prevent brute force and DoS attacks
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // Limit each IP to 100 requests per windowMs
  message: {
    error: 'Too many requests from this IP, please try again later.',
  },
  standardHeaders: true,
  legacyHeaders: false,
});

// Stricter rate limiting for sensitive endpoints
const strictLimiter = rateLimit({
  windowMs: 15 * 60 * 1000,
  max: 10,
  message: {
    error: 'Too many attempts, please try again later.',
  },
});

app.use(limiter);

// Request body size limits to prevent payload overflow
app.use(express.json({ limit: '10kb' }));
app.use(express.urlencoded({ extended: true, limit: '10kb' }));

// ============================================
// VALIDATION MIDDLEWARE
// ============================================

// Validation error handler
const handleValidationErrors = (req, res, next) => {
  const errors = validationResult(req);
  if (!errors.isEmpty()) {
    return res.status(400).json({
      error: 'Validation failed',
      details: errors.array().map(err => ({
        field: err.path,
        message: err.msg,
        value: err.value,
      })),
    });
  }
  next();
};

// Input sanitization helpers
const sanitizeString = (input) => {
  if (typeof input !== 'string') return '';
  return input.trim().replace(/[<>]/g, '');
};

const validateEmail = (email) => {
  const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
  return emailRegex.test(email);
};

const validateId = (id) => {
  const numId = parseInt(id, 10);
  return !isNaN(numId) && numId > 0 && numId <= Number.MAX_SAFE_INTEGER;
};

// ============================================
// ERROR HANDLING MIDDLEWARE
// ============================================

// 404 handler - must be before other error handlers
app.use((req, res) => {
  res.status(404).json({
    error: 'Not Found',
    message: 'The requested resource was not found.',
    path: req.path,
  });
});

// Global error handler - must be last
app.use((err, req, res, next) => {
  // Log error for debugging (in production, use proper logging service)
  console.error('Error:', {
    message: err.message,
    stack: process.env.NODE_ENV === 'development' ? err.stack : undefined,
    path: req.path,
    method: req.method,
    ip: req.ip,
    timestamp: new Date().toISOString(),
  });

  // Don't leak internal error details in production
  const isDevelopment = process.env.NODE_ENV === 'development';

  res.status(err.status || 500).json({
    error: err.name || 'Internal Server Error',
    message: isDevelopment ? err.message : 'An unexpected error occurred.',
    ...(isDevelopment && { stack: err.stack }),
  });
});

// Wrapper for async route handlers to catch errors
const asyncHandler = (fn) => (req, res, next) => {
  Promise.resolve(fn(req, res, next)).catch(next);
};

// ============================================
// ROUTES
// ============================================

// Health check endpoint
app.get('/health', (req, res) => {
  try {
    res.json({ 
      status: 'ok', 
      timestamp: new Date().toISOString(),
      uptime: process.uptime(),
    });
  } catch (error) {
    next(error);
  }
});

// Get all users with pagination and validation
app.get('/users', [
  query('page')
    .optional()
    .isInt({ min: 1 })
    .withMessage('Page must be a positive integer')
    .toInt(),
  query('limit')
    .optional()
    .isInt({ min: 1, max: 100 })
    .withMessage('Limit must be between 1 and 100')
    .toInt(),
  query('search')
    .optional()
    .isString()
    .trim()
    .isLength({ max: 100 })
    .withMessage('Search term must be less than 100 characters'),
  handleValidationErrors,
], asyncHandler(async (req, res) => {
  const { page = 1, limit = 10, search } = req.query;

  const users = [
    { id: 1, name: 'Alice', email: 'alice@example.com' },
    { id: 2, name: 'Bob', email: 'bob@example.com' },
  ];

  // Filter users if search term provided (sanitize input first)
  let filteredUsers = users;
  if (search) {
    const sanitizedSearch = sanitizeString(search);
    filteredUsers = users.filter(user =>
      user.name.toLowerCase().includes(sanitizedSearch.toLowerCase()) ||
      user.email.toLowerCase().includes(sanitizedSearch.toLowerCase())
    );
  }

  // Implement pagination
  const startIndex = (page - 1) * limit;
  const endIndex = page * limit;
  const paginatedUsers = filteredUsers.slice(startIndex, endIndex);

  res.json({
    data: paginatedUsers,
    pagination: {
      page,
      limit,
      total: filteredUsers.length,
      totalPages: Math.ceil(filteredUsers.length / limit),
    },
  });
}));

// Get single user by ID with validation
app.get('/users/:id', [
  param('id')
    .custom(value => {
      if (!validateId(value)) {
        throw new Error('ID must be a valid positive integer');
      }
      return true;
    }),
  handleValidationErrors,
], asyncHandler(async (req, res) => {
  const { id } = req.params;
  const userId = parseInt(id, 10);

  const users = [
    { id: 1, name: 'Alice', email: 'alice@example.com' },
    { id: 2, name: 'Bob', email: 'bob@example.com' },
  ];

  const user = users.find(u => u.id === userId);

  if (!user) {
    const error = new Error('User not found');
    error.status = 404;
    throw error;
  }

  res.json({ data: user });
}));

// Create new user (example of POST with validation)
app.post('/users', strictLimiter, [
  body('name')
    .trim()
    .isLength({ min: 1, max: 100 })
    .withMessage('Name must be between 1 and 100 characters')
    .matches(/^[a-zA-Z\s'-]+$/)
    .withMessage('Name contains invalid characters'),
  body('email')
    .trim()
    .isEmail()
    .withMessage('Invalid email address')
    .normalizeEmail()
    .custom(value => {
      if (!validateEmail(value)) {
        throw new Error('Invalid email format');
      }
      return true;
    }),
  handleValidationErrors,
], asyncHandler(async (req, res) => {
  const { name, email } = req.body;

  // Sanitize inputs
  const sanitizedName = sanitizeString(name);
  const sanitizedEmail = email.trim().toLowerCase();

  // In a real app, you would save to database here
  // Validate no duplicates, etc.

  const newUser = {
    id: Date.now(), // In production, use proper ID generation
    name: sanitizedName,
    email: sanitizedEmail,
  };

  res.status(201).json({
    message: 'User created successfully',
    data: newUser,
  });
}));

// ============================================
// SERVER START
// ============================================

const PORT = process.env.PORT || 3000;

// Graceful shutdown handling
const server = app.listen(PORT, () => {
  console.log(`Server running on port ${PORT}`);
  console.log(`Environment: ${process.env.NODE_ENV || 'development'}`);
});

// Handle graceful shutdown
const gracefulShutdown = (signal) => {
  console.log(`\n${signal} received. Starting graceful shutdown...`);

  server.close(() => {
    console.log('Server closed');
    process.exit(0);
  });

  // Force shutdown after timeout
  setTimeout(() => {
    console.error('Forced shutdown after timeout');
    process.exit(1);
  }, 10000);
};

process.on('SIGTERM', () => gracefulShutdown('SIGTERM'));
process.on('SIGINT', () => gracefulShutdown('SIGINT'));

// Handle uncaught exceptions
process.on('uncaughtException', (error) => {
  console.error('Uncaught Exception:', error);
  gracefulShutdown('uncaughtException');
});

process.on('unhandledRejection', (reason, promise) => {
  console.error('Unhandled Rejection at:', promise, 'reason:', reason);
  gracefulShutdown('unhandledRejection');
});

module.exports = app;

# Security Review: app.js

## Executive Summary

This review identifies significant security vulnerabilities in the current `app.js` implementation and provides comprehensive recommendations for implementing security best practices.

---

## Critical Issues Found

### 1. ❌ No Error Handling Middleware
**Risk:** High
**Impact:** Unhandled exceptions can crash the server, leak sensitive information, or leave users without meaningful error messages.

**Current:** No error handling
```javascript
// Missing: Error handling middleware
```

**Recommendation:** Implement global error handler
```javascript
app.use((err, req, res, next) => {
  console.error('Error:', err.message);
  res.status(err.status || 500).json({
    error: 'Internal Server Error',
    message: process.env.NODE_ENV === 'development' ? err.message : 'An error occurred'
  });
});
```

---

### 2. ❌ No Input Validation
**Risk:** Critical
**Impact:** SQL injection, XSS, command injection, data corruption

**Current:** All inputs accepted without validation
```javascript
app.get('/users/:id', (req, res) => {
  // No validation of req.params.id
});
```

**Recommendation:** Use express-validator for comprehensive validation
```javascript
const { validationResult } = require('express-validator');

app.get('/users/:id',
  param('id').isInt().withMessage('ID must be an integer'),
  (req, res) => {
    const errors = validationResult(req);
    if (!errors.isEmpty()) {
      return res.status(400).json({ errors: errors.array() });
    }
    // Safe to use validated input
  }
);
```

---

### 3. ❌ No Rate Limiting
**Risk:** High
**Impact:** DoS attacks, brute force attacks, API abuse

**Current:** No rate limiting implemented

**Recommendation:** Implement express-rate-limit
```javascript
const rateLimit = require('express-rate-limit');

const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100 // limit each IP to 100 requests per windowMs
});

app.use(limiter);
```

---

### 4. ❌ Missing Security Headers
**Risk:** High
**Impact:** XSS, clickjacking, MIME-sniffing attacks, missing HTTPS enforcement

**Current:** No security headers set

**Recommendation:** Use Helmet middleware
```javascript
const helmet = require('helmet');
app.use(helmet());
```

**Headers added:**
- `Content-Security-Policy`: Prevents XSS
- `X-Frame-Options`: Prevents clickjacking
- `X-Content-Type-Options`: Prevents MIME-sniffing
- `Strict-Transport-Security`: Enforces HTTPS
- `X-XSS-Protection`: XSS protection

---

### 5. ❌ No Request Size Limits
**Risk:** Medium
**Impact:** Memory exhaustion attacks, payload overflow

**Current:** No payload size restrictions

**Recommendation:** Set appropriate limits
```javascript
app.use(express.json({ limit: '10kb' }));
app.use(express.urlencoded({ extended: true, limit: '10kb' }));
```

---

### 6. ❌ Unhandled Routes Return No Response
**Risk:** Low
**Impact:** Poor user experience, information leakage

**Current:** Invalid routes hang without response

**Recommendation:** Implement 404 handler
```javascript
app.use((req, res) => {
  res.status(404).json({
    error: 'Not Found',
    path: req.path
  });
});
```

---

### 7. ❌ No CORS Configuration
**Risk:** Medium
**Impact:** Unauthorized cross-origin requests, CSRF attacks

**Current:** CORS not configured

**Recommendation:** Configure CORS properly
```javascript
const cors = require('cors');

app.use(cors({
  origin: process.env.ALLOWED_ORIGINS?.split(',') || ['http://localhost:3000'],
  credentials: true,
  methods: ['GET', 'POST', 'PUT', 'DELETE'],
  allowedHeaders: ['Content-Type', 'Authorization']
}));
```

---

## Additional Security Recommendations

### 8. Input Sanitization
**Purpose:** Remove potentially malicious characters from user input

```javascript
const sanitizeString = (input) => {
  if (typeof input !== 'string') return '';
  return input.trim().replace(/[<>]/g, '');
};
```

### 9. Async Error Handling
**Purpose:** Catch errors in async route handlers

```javascript
const asyncHandler = (fn) => (req, res, next) => {
  Promise.resolve(fn(req, res, next)).catch(next);
};

app.get('/users', asyncHandler(async (req, res) => {
  // Async code here
}));
```

### 10. Environment-Based Configuration
**Purpose:** Different settings for development vs production

```javascript
const isDevelopment = process.env.NODE_ENV === 'development';

// Only show stack traces in development
res.json({
  error: err.message,
  ...(isDevelopment && { stack: err.stack })
});
```

### 11. Logging and Monitoring
**Purpose:** Audit trail for security events

```javascript
app.use((req, res, next) => {
  console.log({
    method: req.method,
    path: req.path,
    ip: req.ip,
    userAgent: req.get('user-agent'),
    timestamp: new Date().toISOString()
  });
  next();
});
```

### 12. Graceful Shutdown
**Purpose:** Handle server shutdown properly

```javascript
process.on('SIGTERM', () => {
  server.close(() => {
    console.log('Server closed');
    process.exit(0);
  });
});
```

### 13. Unhandled Exception Handlers
**Purpose:** Prevent server crashes from unexpected errors

```javascript
process.on('uncaughtException', (error) => {
  console.error('Uncaught Exception:', error);
  process.exit(1);
});

process.on('unhandledRejection', (reason, promise) => {
  console.error('Unhandled Rejection:', reason);
});
```

---

## Required Dependencies

Add to package.json:

```json
{
  "dependencies": {
    "helmet": "^7.1.0",
    "express-rate-limit": "^7.1.5",
    "express-validator": "^7.0.1",
    "cors": "^2.8.5"
  }
}
```

Install with:
```bash
npm install helmet express-rate-limit express-validator cors
```

