      expect(response.status).toBe(400);
      expect(response.body.error).toContain('Validation failed');
    });

    test('should reject negative user ID', async () => {
      const response = await request(app).get('/users/-1');
      expect(response.status).toBe(400);
      expect(response.body.error).toContain('Validation failed');
    });

    test('should reject zero user ID', async () => {
      const response = await request(app).get('/users/0');
      expect(response.status).toBe(400);
      expect(response.body.error).toContain('Validation failed');
    });

    test('should accept valid user ID', async () => {
      const response = await request(app).get('/users/1');
      expect([200, 404]).toContain(response.status); // 404 if user doesn't exist
      expect(response.body.error).not.toContain('Validation failed');
    });

    test('should reject page number > 100', async () => {
      const response = await request(app).get('/users?page=101');
      expect(response.status).toBe(400);
      expect(response.body.error).toContain('Validation failed');
    });

    test('should reject limit > 50', async () => {
      const response = await request(app).get('/users?limit=51');
      expect(response.status).toBe(400);
      expect(response.body.error).toContain('Validation failed');
    });

    test('should reject search term > 100 characters', async () => {
      const longSearch = 'a'.repeat(101);
      const response = await request(app).get(`/users?search=${longSearch}`);
      expect(response.status).toBe(400);
      expect(response.body.error).toContain('Validation failed');
    });
  });

  describe('Response Headers', () => {
    test('should include security headers', async () => {
      const response = await request(app).get('/health');
      expect(response.headers).toHaveProperty('x-content-type-options');
      expect(response.headers['x-content-type-options']).toBe('nosniff');
      expect(response.headers).toHaveProperty('x-frame-options');
    });
  });

  describe('Error Handling', () => {
    test('should return 404 for non-existent routes', async () => {
      const response = await request(app).get('/nonexistent');
      expect(response.status).toBe(404);
      expect(response.body.error).toBe('Not Found');
    });

    test('should not expose stack traces in production', async () => {
      const originalEnv = process.env.NODE_ENV;
      process.env.NODE_ENV = 'production';

      const response = await request(app).get('/users/invalid');

      expect(response.body).not.toHaveProperty('stack');
      process.env.NODE_ENV = originalEnv;
    });

    test('should expose stack traces in development', async () => {
      const originalEnv = process.env.NODE_ENV;
      process.env.NODE_ENV = 'development';

      const response = await request(app).get('/users/invalid');

      // In development mode, more detailed error info is acceptable
      expect(response.body).toHaveProperty('error');
      process.env.NODE_ENV = originalEnv;
    });
  });

  describe('Health Check', () => {
    test('should return health status', async () => {
      const response = await request(app).get('/health');
      expect(response.status).toBe(200);
      expect(response.body).toHaveProperty('status', 'ok');
      expect(response.body).toHaveProperty('timestamp');
    });
  });

  describe('Rate Limiting', () => {
    test('should enforce rate limits', async () => {
      // This test would need adjustment based on your rate limiter settings
      // For demonstration, we'll show the structure

      // Make 101 requests (assuming limit is 100)
      const requests = [];
      for (let i = 0; i < 101; i++) {
        requests.push(request(app).get('/users'));
      }

      const responses = await Promise.all(requests);
      const rateLimitedResponses = responses.filter(r => r.status === 429);

      // At least last request should be rate limited
      expect(rateLimitedResponses.length).toBeGreaterThan(0);
    }, 30000); // Increase timeout for this test
  });

  describe('XSS Prevention', () => {
    test('should sanitize HTML in search', async () => {
      const xssPayload = '<script>alert("XSS")</script>';
      const response = await request(app).get(`/users?search=${encodeURIComponent(xssPayload)}`);

      expect(response.status).toBe(200);
      // The response should not contain the unescaped script tag
      if (response.body.data && response.body.data.length > 0) {
        const dataString = JSON.stringify(response.body);
        expect(dataString).not.toContain('<script>');
      }
    });
  });
});

